mapper.update:

update public.account_cnt_statistics 
   set value1 = case when to_char(now(),'yyyymmdd') = to_char(now(),'yyyymm')||'01' then #{userCnt} else value1 end 
      ,value2 = #{userCnt}
      ,value3 = #{dayEnableCnt}
      ,value4 = #{monthEnableCnt}
      ,updated_at = now()
 where year_month = to_char(now(),'yyyymm')
   and user_type_cd = case when #{userTypeCd} = '' then '99' else #{userTypeCd} end
